<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';$p=db();
if(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){method('GET');$ph=phone($_GET['phone']??'');if(strlen(preg_replace('/\D/','',$ph)??'')<10||strlen($ph)>16)reply(400,['ok'=>false,'message'=>'Enter a valid mobile number.']);limit('order-lookup',15);$q=$p->prepare('SELECT order_number,status,fulfillment,total,created_at FROM orders WHERE customer_id=(SELECT id FROM customers WHERE phone=? LIMIT 1) ORDER BY id DESC LIMIT 20');$q->execute([$ph]);reply(200,['ok'=>true,'orders'=>$q->fetchAll()]);}
method('POST');same_origin();limit('order-create',8);$d=body();$name=clean($d['name']??'',100);$ph=phone($d['phone']??'');$digits=preg_replace('/\D/','',$ph)??'';$email=clean($d['email']??'',190);$addr=clean($d['address']??'',500);$pref=clean($d['preferences']??'',500);$lat=isset($d['customer_latitude'])&&is_numeric($d['customer_latitude'])?(float)$d['customer_latitude']:null;$lng=isset($d['customer_longitude'])&&is_numeric($d['customer_longitude'])?(float)$d['customer_longitude']:null;if($lat!==null&&($lat < -90||$lat>90))$lat=null;if($lng!==null&&($lng < -180||$lng>180))$lng=null;$ful=clean($d['fulfillment']??'Pickup',20);$pay=clean($d['payment_method']??'At Restaurant',30);$items=$d['items']??[];
if($name===''||strlen($digits)<10||strlen($ph)>16)reply(422,['ok'=>false,'message'=>'Enter your name and a valid mobile number.']);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))reply(422,['ok'=>false,'message'=>'Enter a valid email.']);if(!in_array($ful,['Pickup','Delivery'],true)||!in_array($pay,['At Restaurant','Online'],true))reply(422,['ok'=>false,'message'=>'Invalid checkout option.']);if($ful==='Delivery'&&$addr==='')reply(422,['ok'=>false,'message'=>'Delivery address is required.']);if(!is_array($items)||count($items)<1||count($items)>40)reply(422,['ok'=>false,'message'=>'Cart is empty or too large.']);$qty=[];foreach($items as $it){$id=filter_var($it['menu_item_id']??null,FILTER_VALIDATE_INT);$n=filter_var($it['quantity']??null,FILTER_VALIDATE_INT);if(!$id||!$n||$n<1||$n>30)reply(422,['ok'=>false,'message'=>'Invalid item quantity.']);$qty[$id]=($qty[$id]??0)+$n;if($qty[$id]>30)reply(422,['ok'=>false,'message'=>'Maximum 30 of each item.']);}
try{$p->beginTransaction();$cid=upsert_customer($p,$ph,['name'=>$name,'email'=>$email,'address'=>$addr]);$ids=array_keys($qty);$marks=implode(',',array_fill(0,count($ids),'?'));$q=$p->prepare("SELECT id,name,price FROM menu_items WHERE is_available=1 AND id IN ($marks)");$q->execute($ids);$menu=[];foreach($q->fetchAll() as $m)$menu[(int)$m['id']]=$m;if(count($menu)!==count($ids))throw new DomainException('A selected dish is unavailable. Refresh the menu.');$sum=0;foreach($qty as $id=>$n)$sum+=(float)$menu[$id]['price']*$n;$sum=round($sum,2);$num='LBFP-'.gmdate('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$q=$p->prepare("INSERT INTO orders(order_number,customer_id,status,fulfillment,payment_method,address,customer_latitude,customer_longitude,preferences,subtotal,total,created_at,updated_at) VALUES(?,?,'Received',?,?,?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())");$q->execute([$num,$cid,$ful,$pay,$ful==='Delivery'?$addr:'',$ful==='Delivery'?$lat:null,$ful==='Delivery'?$lng:null,$pref,$sum,$sum]);$oid=(int)$p->lastInsertId();$ins=$p->prepare('INSERT INTO order_items(order_id,menu_item_id,item_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)');foreach($qty as $id=>$n){$m=$menu[$id];$ins->execute([$oid,$id,$m['name'],$m['price'],$n,round((float)$m['price']*$n,2)]);}$p->commit();reply(201,['ok'=>true,'order'=>['order_number'=>$num,'status'=>'Received','total'=>$sum,'fulfillment'=>$ful]]);}catch(DomainException $e){if($p->inTransaction())$p->rollBack();reply(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($p->inTransaction())$p->rollBack();error_log('LBFP order error: '.$e->getMessage());reply(500,['ok'=>false,'message'=>'Unable to save the order right now.']);}
